package com.lastsignal.entity.client;

import com.lastsignal.LastSignalMod;
import com.lastsignal.entity.HorrorEntity;
import net.minecraft.resources.ResourceLocation;
import software.bernie.geckolib.model.GeoModel;

/** Client-only. Geo model / animation / texture resolved from the entity's profile id (generated by tools/monsters.py). */
public class HorrorGeoModel extends GeoModel<HorrorEntity> {
    @Override
    public ResourceLocation getModelResource(HorrorEntity e) {
        return new ResourceLocation(LastSignalMod.MODID, "geo/" + e.profileId + ".geo.json");
    }

    @Override
    public ResourceLocation getTextureResource(HorrorEntity e) {
        return new ResourceLocation(LastSignalMod.MODID, "textures/entity/" + e.profileId + ".png");
    }

    @Override
    public ResourceLocation getAnimationResource(HorrorEntity e) {
        return new ResourceLocation(LastSignalMod.MODID, "animations/" + e.profileId + ".animation.json");
    }
}
